const icons={conversation:'<path d="M14 14H7l-4 3V5a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2Z"/><path d="M8 18h9l4 3V10a2 2 0 0 0-2-2"/>',book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z"/><path d="M20 4h-4a3 3 0 0 0-3 3m0 14a4 4 0 0 1 4-2h3V4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>',quiz:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 2h6v4H9zM9 12l2 2 4-4m-6 8h6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V7m5 9V4"/>',speaker:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="m11 4-6 5H2v6h3l6 5zM16 9l5 6m0-6-5 6"/>',check:'<path d="m5 12 4 4L19 6"/>',left:'<path d="m14 6-6 6 6 6M8 12h13"/>',right:'<path d="m10 6 6 6-6 6M16 12H3"/>',shuffle:'<path d="m17 3 4 4-4 4M3 17 17 7h4M3 7l5 4m5 2 4 4h4m-4-4 4 4-4 4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>'};

const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;

const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const $=s=>document.querySelector(s);

const navs=[['daily','sun','每日一学'],['study','book','词汇学习'],['scenes','conversation','情景训练'],['review','repeat','温故知新'],['quiz','quiz','课程测验'],['dictionary','search','词库检索'],['progress','chart','学习进度']];

let sourceData,data,words,levels,byId,byThai,progress,saveQueue=Promise.resolve(),quiz=null,quizAdvanceTimer=null,audio=null,audioToken=0,toastTimer,filterTimer,pendingImport=null;

const state={view:'study',level:'入门',quizLevel:'入门',wordId:0,history:[],dailyHistory:[],dailyWord:null,dailyKey:null,muted:false,filters:{term:'',level:'全部等级',pos:'全部词性',unlearned:false},dictPage:0};

const scenes=createScenarios({esc,locale,icon,words:()=>words,progress:()=>progress,isLearned:w=>isLearned(w),muted:()=>state.muted,render,cancelAudio,tokenAudio:t=>exampleTokenAudio[t]||data.token_audio?.[t]||byThai.get(t)?.audio,

  mark:w=>{

    if(w.source==='existing'){if(!isLearned(w))progress[w.level].learned.push(w.thai);}

    else {progress._scenes ||= {learned:[]};if(!progress._scenes.learned.includes(w.thai))progress._scenes.learned.push(w.thai);}

    saveProgress();

  }

});

const LOCAL_OWNER=['127.0.0.1','localhost','[::1]'].includes(location.hostname);

const STORAGE=LOCAL_OWNER?'thai-studio-progress-v1':'thai-studio-personal-progress-v2';

let studyAudioKey=null;

let wrongStudy=null;

function clearWrongWords(){wrongStudy=null;if(quiz){quiz.wrongIds=[];quiz.wrongStudyDone=false;}}

let detailId=null,dictionarySnapshot=null;

let preserveStudySelection=false;

let manualAudioCounts=new WeakMap();

const button=(label,action,style='',attrs='')=>`<button class="button ${style}" data-action="${action}" ${attrs}>${label}</button>`;

const percent=(n,total)=>total?Math.round(n/total*100):0;

const format=n=>n.toLocaleString(locale());

const isLearned=w=>progress[w.level].learned.includes(w.thai);

const totalLearned=()=>levels.reduce((s,l)=>s+progress[l].learned.length,0);

const roman=(item,field='roman')=>esc(item[field]||'')+(item[field+'_kind']?.includes('自动')?' <span class="pron-note">（自动转写）</span>':'');

function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}

function showModal(html){detailId=null;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}

function closeModal(){$('#modal').close();pendingImport=null;detailId=null;}

function saveProgress(){

  progress._web={updated_at:Date.now(),muted:state.muted,quizLevel:state.quizLevel};

  try{

    localStorage.setItem(STORAGE,JSON.stringify(progress));

    $('#save-status').textContent='个人进度已保存';

  }catch{

    $('#save-status').textContent='进度未保存';

    toast('浏览器无法保存进度，请在学习进度页导出备份。');

  }

  return Promise.resolve();

}

function cancelAudio(){audioToken++;if(audio){audio.pause();audio.removeAttribute('src');audio.load();audio=null;}document.querySelectorAll('[data-audio].playing').forEach(el=>el.classList.remove('playing'));}

function playManualAudio(button){

  if(state.muted||button.disabled)return;

  const count=manualAudioCounts.get(button)||0;

  manualAudioCounts.set(button,(count+1)%4);

  return playAudio(button.dataset.audio,count<2?1:0.5);

}

const audioRevisions={"4b9c229c455b2ccbbf4a5b71654b6533ad62cf1e7525269d6c57d7a1194978c6.mp3":'20260917-prakanphai-female-2'};

async function playAudio(filename,rate=1){

  if(state.muted)return;

  cancelAudio();const token=audioToken;

  const audioDirectory=data.metadata.audio_directory||'audio/';

  const audioVersion=data.metadata.audio_version||audioRevisions[filename]||'20260917-token-audio-2';

  audio=new Audio(new URL(audioDirectory+filename+'?v='+audioVersion,location.href).href);audio.preload='auto';audio.playbackRate=rate;audio.preservesPitch=true;

  try{await audio.play();if(token!==audioToken)return;document.querySelectorAll(`[data-audio="${filename}"]`).forEach(el=>el.classList.add('playing'));audio.onended=()=>document.querySelectorAll('[data-audio].playing').forEach(el=>el.classList.remove('playing'));}

  catch(error){if(token!==audioToken||state.muted)return;toast(error.name==='NotAllowedError'?'浏览器需要先点击一次喇叭才能发声。':'这段音频未能播放，请确认 audio 文件夹完整。');}

}

function audioButton(filename,label='播放发音',mini=true){return `<button class="${mini?'icon-button audio-mini':'play-word'}" data-audio="${filename}" aria-label="${esc(label)}" title="${esc(label)} · 手动播放：两次正常、两次慢速" ${state.muted?'disabled':''}>${icon('speaker')}${mini?'':'单词发音'}</button>`;}

function updateMute(){const b=$('#mute-button');b.innerHTML=icon(state.muted?'mute':'speaker');b.setAttribute('aria-pressed',String(state.muted));b.setAttribute('aria-label',state.muted?'取消静音':'开启静音');b.title=state.muted?'静音已开启':'点击静音';document.querySelectorAll('[data-audio]').forEach(b=>b.disabled=state.muted);}

function setView(view){if(!navs.some(x=>x[0]===view))view='study';if(location.hash!=='#'+view)location.hash=view;else route();}

function randomUnlearnedId(level=state.level){return sample(words.filter(w=>w.level===level&&!isLearned(w)),1)[0]?.id??null;}

function syncDaily(){

  const before=JSON.stringify(progress._daily),d=ensureDaily(progress,words,levels);

  const key=JSON.stringify([d.date,d.round,d.words]);

  if(state.dailyKey!==key){state.dailyKey=key;state.dailyHistory=[];state.dailyWord=null;}

  const remaining=d.words.filter(t=>!d.done.includes(t));

  if(!remaining.includes(state.dailyWord))state.dailyWord=remaining[0]||null;

  if(!state.dailyWord)state.dailyHistory=[];

  if(before!==JSON.stringify(d))saveProgress();

}

function route(){

  const previousView=state.view;

  const hashView=location.hash.split('/')[0];

  const nextView=navs.some(x=>'#'+x[0]===hashView)?hashView.slice(1):'study';

  if(nextView!==state.view){clearWrongWords();cancelAudio();cancelQuizAdvance();}

  state.view=nextView;

  if(state.view==='study'){

    if(previousView!=='study'&&!preserveStudySelection){state.wordId=randomUnlearnedId();state.history=[];}

    preserveStudySelection=false;

  }

  if(state.view==='daily')syncDaily();

  render();

  if(state.view==='quiz')scheduleQuizAdvance();

}

function render(){

  $('#nav').innerHTML=navs.map(([key,i,name])=>`<a class="nav-item ${state.view===key?'active':''}" href="#${key}" ${state.view===key?'aria-current="page"':''}>${icon(i)}${name}${key==='daily'?'<span class="nav-count">10</span>':''}</a>`).join('');

  $('#page-name').textContent=navs.find(x=>x[0]===state.view)[2];

  if(state.view==='study'||state.view==='daily')renderStudy();

  else if(state.view==='quiz'||state.view==='review')renderQuiz();

  else if(state.view==='scenes')scenes.render();

  else if(state.view==='dictionary')renderDictionary();

  else {

    renderProgress();

    $('#main').insertAdjacentHTML('beforeend',`<section class="side-card"><h2>情景训练</h2><p>场景补充词已掌握 <strong>${progress._scenes?.learned.length||0}</strong></p><a class="button soft" href="#scenes">情景训练 →</a></section>`);

  }

  updateMute();

  const studyWord=wrongStudy&&state.view==='quiz'?currentWord():['study','daily'].includes(state.view)?currentWord():state.view==='scenes'?scenes.currentWord():null;

  const nextStudyAudioKey=studyWord?`${state.view}:${state.view==='scenes'?location.hash+':':''}${studyWord.id}`:null;

  if(nextStudyAudioKey!==studyAudioKey){

    cancelAudio();studyAudioKey=nextStudyAudioKey;manualAudioCounts=new WeakMap();

    if(studyWord?.audio)playAudio(studyWord.audio);

  }

}

function heading(title,subtitle,right=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${right}</div>`;}

function levelTabs(forQuiz=false){const selected=forQuiz?state.quizLevel:state.level;return `<div class="level-tabs" aria-label="${forQuiz?'测验难度':'课程等级'}">${levels.map(l=>`<button class="level-tab ${l===selected?'active':''}" data-action="${forQuiz?'quiz-level':'level'}" data-level="${l}" aria-pressed="${l===selected}">${l}</button>`).join('')}</div>`;}

function currentWord(){if(wrongStudy&&state.view==='quiz')return byId.get(wrongStudy.ids[wrongStudy.index]);return state.view==='daily'?byThai.get(state.dailyWord):byId.get(state.wordId);}

function examples(word){return `<div class="section-heading"><h2>例句与用法</h2><small>点击发音：两次正常 · 两次慢速</small></div>${word.senses.filter(s=>s.example && s.example_cn).map((s,i)=>`<article class="example-card"><div class="example-head"><div class="sense-title"><span class="sense-index">${String(i+1).padStart(2,'0')}</span>${usageTitle(s,esc,locale())}</div></div>${renderUsage(s,esc,locale(),state.muted)}${s.introductory_example?'<p class="note">词义介绍例句</p>':''}${s.roman&&s.roman!==word.roman?`<p class="example-pron">此义读音：${esc(s.roman)}</p>`:''}${renderExampleAudio(s.audio,esc,locale(),state.muted,icon('speaker'))}<div class="interlinear" aria-label="泰语例句与逐词中文，点击词语发音">${(s.example_tokens||[[s.example,'']]).map(([t,g])=>{const filename=exampleTokenAudio[t]||data.token_audio?.[t]||byThai.get(t)?.audio;return filename?`<button type="button" class="token token-audio" data-audio="${esc(filename)}" aria-label="播放词语 ${esc(t)}，${esc(g)}" title="点击发音：两次正常、两次慢速" ${state.muted?'disabled':''}><span class="thai" lang="th">${esc(t)}</span><span class="gloss" lang="${locale()}">${esc(g)}</span></button>`:`<span class="token"><span class="thai" lang="th">${esc(t)}</span><span class="gloss" lang="${locale()}">${esc(g)}</span></span>`;}).join(' ')}</div><p class="translation">${esc(s.example_cn)}</p>${s.example_cn_kind?.includes('自动')?'<p class="note translation-note">自动翻译 · 待校核</p>':''}</article>`).join('')}`;}

function studyRail(word){const count=progress[word.level].learned.length,total=words.filter(w=>w.level===word.level).length;return `<aside class="study-rail"><section class="side-card"><h2>当前课程进度</h2><div class="progress-ring" style="--value:${percent(count,total)}%"><div class="ring-value">${count}<small>已掌握词汇</small></div></div><div class="metric-row"><span>当前课程</span><strong>${word.level}</strong></div><div class="metric-row"><span>完成比例</span><strong>${percent(count,total)}%</strong></div><div class="metric-row"><span>课程词汇</span><strong>${format(total)} 个</strong></div>${button('查看学习进度','go-progress','soft')}</section><section class="side-card review"><div class="review-icon">${icon('repeat')}</div><h2>温故知新</h2><p>从已掌握的词汇中抽取 10 个，看看还记得多少。</p>${button('开始复习','start-review')}</section><p class="shortcut">按 <kbd>←</kbd> <kbd>→</kbd> 切换词汇<br>点击“已掌握”后自动下一个</p></aside>`;}

function renderStudy(){

  const daily=state.view==='daily',d=progress._daily;

  const top=heading(daily?'每日一学':'词汇学习',daily?'每组随机学习 10 个未掌握词汇，学完后可再来一组。':`${state.level} · ${esc(data.level_info[state.level].split('\n')[0])}`,`<span class="today-label">${localDate().replaceAll('-',' / ')}</span>`);

  if(daily&&!state.dailyWord){

    const total=d.words.length,studied=d.studied.length,available=dailyCandidates(progress,words,levels).length;

    $('#main').innerHTML=top+`<section class="word-card empty"><span class="tag learned">${total?`第 ${d.round} 组已完成`:'全部词汇已掌握'}</span><h2>${total?'当日学习已完成':'全部词汇已掌握'}</h2><p>${total?`本组 ${total} 个词已学完，今日累计已学 ${studied} 个。`:'可以进入温故知新，继续巩固记忆。'}</p><p>${available?`是否再学一组？下一组随机抽取 ${Math.min(10,available)} 个未掌握且今天未学过的词汇。`:total?'今天可学习的词汇已全部学完，明天可继续学习未掌握的词汇。':'暂无未掌握词汇可抽取。'}</p>${button(icon('repeat')+'再来一组','daily-again','primary',available?'':'disabled')}${button('结束学习','finish-daily','ghost')}${!total?button('温故知新','start-review','ghost'):''}</section>`;

    return;

  }

  const word=currentWord();

  if(!word){$('#main').innerHTML=top+levelTabs()+`<section class="word-card empty"><span class="tag learned">当前等级已完成</span><h2>${state.level}词汇已全部掌握</h2><p>可以切换其他等级继续学习，或进入温故知新巩固记忆。</p>${button(icon('repeat')+'温故知新','start-review','primary')}${button('查看学习进度','go-progress','ghost')}</section>`;return;}

  const index=words.filter(w=>w.level===word.level).findIndex(w=>w.id===word.id)+1;

  $('#main').innerHTML=top+(daily?`<div class="session-banner"><p>第 ${d.round} 组 · 本组已学 <strong>${d.done.length} / ${d.words.length}</strong> 个 · 今日累计 ${d.studied.length} 个</p><div class="progress-track" role="progressbar" aria-label="本组完成进度" aria-valuemin="0" aria-valuemax="${d.words.length}" aria-valuenow="${d.done.length}"><span style="width:${percent(d.done.length,d.words.length)}%"></span></div></div>`:levelTabs())+`<div class="study-layout"><div class="learning-column"><article class="word-card"><div class="word-meta"><span class="tag ${isLearned(word)?'learned':''}">${word.level} · ${isLearned(word)?'已掌握':esc((word.pos||[]).join(' / ')||'基础词汇')}</span><span>第 ${index} / ${words.filter(w=>w.level===word.level).length} 个</span></div><div class="word-center"><h2 class="word-thai ${word.thai.length>18?'long':''}" lang="th">${esc(word.thai)}</h2><p class="pron">${roman(word)}</p><p class="word-cn"><span>${esc(word.senses.map(s=>s.cn).join(' / '))}</span></p>${audioButton(word.audio,'播放单词 '+word.thai,false)}</div><div class="word-footer">${button(icon('left')+'上一个','previous','ghost',!(daily?state.dailyHistory:state.history).length?'disabled':'')}${button(icon('check')+'已掌握','master','primary')}${button('下一个'+icon('right'),'next','ghost')}</div></article>${examples(word)}</div>${studyRail(word)}</div>`;

}

function advance(master=false){

  if(!['study','daily'].includes(state.view))return;

  if(state.view==='daily'&&progress._daily?.date!==localDate()){cancelAudio();syncDaily();render();return;}

  const word=currentWord();if(!word)return;cancelAudio();

  if(master&&!isLearned(word)){progress[word.level].learned.push(word.thai);toast(`已掌握「${word.thai}」`);}

  if(state.view==='daily'){

    const d=progress._daily;if(!d.done.includes(word.thai))d.done.push(word.thai);

    ensureDaily(progress,words,levels);state.dailyHistory.push(word.thai);

    state.dailyWord=d.words.find(t=>!d.done.includes(t))||null;

    if(!state.dailyWord)state.dailyHistory=[];

    saveProgress();

  }else{

    const unlearned=words.filter(w=>w.level===state.level&&!isLearned(w));

    const candidates=unlearned.filter(w=>w.id!==word.id);

    const next=sample(candidates,1)[0]||unlearned.find(w=>w.id===word.id);

    if(next?.id!==word.id)state.history.push(word.id);

    state.wordId=next?.id??null;

    if(master)saveProgress();

  }

  render();

}

function previous(){cancelAudio();if(state.view==='study'&&state.history.length)state.wordId=state.history.pop();if(state.view==='daily'){if(progress._daily?.date!==localDate())syncDaily();else if(state.dailyWord&&state.dailyHistory.length)state.dailyWord=state.dailyHistory.pop();}render();}

function setLevel(level){if(!levels.includes(level))return;state.level=level;state.wordId=randomUnlearnedId(level);state.history=[];cancelAudio();render();}

function quizIntro(mode){const review=mode==='review',count=review?totalLearned():words.filter(w=>w.level===state.quizLevel&&w.quiz_eligible!==false).length;return `${heading(review?'温故知新':'课程测验',review?'熟悉的词，再记牢一点。':'听发音、看泰语，选出正确的中文意思。')}${review?'':'<p class="quiz-level-label">测验难度 · 独立于词汇学习</p>'+levelTabs(true)}<section class="quiz-wrap quiz-card empty"><span class="tag">${review?'已掌握词汇复习':state.quizLevel+'课程'}</span><h2>${review?'检验你的词汇记忆':'准备好，开始这一轮。'}</h2><p>${review?`已掌握 ${count} 个词汇，本轮随机抽取 ${Math.min(10,count)} 个。`:`本轮随机抽取 ${Math.min(20,count)} 题，每题自动发音一次。答对后自动进入下一题；答错时高亮正确答案，点击下一题继续。`}</p>${!count?'<p>先在词汇学习中点击“已掌握”，再来复习。</p>':''}<div class="quiz-result-actions quiz-intro-actions">${button(icon(review?'repeat':'quiz')+'开始'+(review?'复习':'测验'),review?'start-review':'start-quiz','primary',!count?'disabled':'')}${!count?button('去学习词汇','go-study','ghost'):''}</div></section>`;}

function cancelQuizAdvance(){clearTimeout(quizAdvanceTimer);quizAdvanceTimer=null;}

function scheduleQuizAdvance(){

  cancelQuizAdvance();

  if(!quiz||quiz.complete||quiz.mode!=='course'||state.view!=='quiz'||location.hash!=='#quiz')return;

  const session=quiz,questionIndex=quiz.index,question=quiz.questions[questionIndex];

  if(quiz.selected!==question.answerIndex)return;

  quizAdvanceTimer=setTimeout(()=>{

    quizAdvanceTimer=null;

    if(quiz===session&&quiz.index===questionIndex&&!quiz.complete&&quiz.selected===question.answerIndex&&state.view==='quiz'&&location.hash==='#quiz')nextQuestion();

  },600);

}

function startQuiz(mode){

  clearWrongWords();cancelQuizAdvance();

  const questions=makeQuiz(words,progress,levels,mode,state.quizLevel);if(!questions.length){setView(mode==='review'?'review':'quiz');toast(mode==='review'?'还没有已掌握的词汇，先学习几个吧。':'当前课程暂无可用题目。');return;}

  const meaningIds=new Map(words.map(w=>[w.cn,w.id]));

  for(const question of questions){

    question.answerIndex=question.options.indexOf(question.answer);

    question.optionIds=question.options.map((text,index)=>index===question.answerIndex?question.id:meaningIds.get(text));

  }

  quiz={mode,level:state.quizLevel,questions,index:0,score:0,selected:null,complete:false,wrongIds:[],wrongStudyDone:false};

  const target=mode==='review'?'review':'quiz';state.view=target;if(location.hash!=='#'+target)history.replaceState(null,'','#'+target);cancelAudio();render();playCurrentQuestion();

}

function playCurrentQuestion(){if(quiz&&!quiz.complete){const word=byId.get(quiz.questions[quiz.index].id);playAudio(word.audio);}}

function renderQuiz(){

  if(state.view==='quiz'&&wrongStudy){renderWrongStudy();return;}

  const mode=state.view==='review'?'review':'course';

  if(!quiz||quiz.mode!==mode){$('#main').innerHTML=quizIntro(mode);return;}

  const title=mode==='review'?'温故知新':'课程测验';const head=heading(title,`${mode==='review'?'已掌握词汇复习':quiz.level+'课程'} · ${quiz.questions.length} 题`,'<div class="quiz-heading-actions">'+(mode==='course'?button('选择难度','choose-quiz-level','ghost small'):'')+button('重新开始','restart-quiz','ghost small')+'</div>');

  if(quiz.complete){const score=Math.round(quiz.score/quiz.questions.length*100);$('#main').innerHTML=head+`<section class="quiz-wrap quiz-card empty"><span class="tag learned">本轮${mode==='review'?'复习':'测验'}完成</span><div class="result-score">${score}<small> 分</small></div><h2>${score===100?'全部答对，记得很牢。':score>=60?'不错，再巩固一下。':'多练几次，会越来越熟悉。'}</h2><p>答对 ${quiz.score} / ${quiz.questions.length} 题${mode==='course'?` · ${quiz.level}历史最高 ${progress[quiz.level].best_score} 分`:''}</p>${quiz.wrongStudyDone?'<p class="success-text">错词学习完成，本轮错词已清空。</p>':''}<div class="quiz-result-actions">${mode==='course'&&quiz.wrongIds?.length?button('错词学习（'+quiz.wrongIds.length+'）','study-mistakes','primary'):''}${button(icon('repeat')+'再来一轮','restart-quiz',quiz.wrongIds?.length?'soft':'primary')}${button('返回词汇学习','go-study','ghost')}</div></section>`;return;}

  const question=quiz.questions[quiz.index],word=byId.get(question.id),answered=quiz.selected!==null,correct=quiz.selected===question.answerIndex;

  $('#main').innerHTML=head+`<section class="quiz-wrap quiz-card"><div class="quiz-head"><span>第 <strong>${quiz.index+1}</strong> / ${quiz.questions.length} 题</span><span>已答对 ${quiz.score} 题</span></div><div class="progress-track"><span style="width:${percent(quiz.index,quiz.questions.length)}%"></span></div><div class="quiz-prompt"><h2 class="word-thai ${word.thai.length>18?'long':''}" lang="th">${esc(word.thai)}</h2>${audioButton(word.audio,'再次播放当前题目')}${mode==='course'&&word.roman?`<p class="pron quiz-pron" aria-label="罗马拼音">${roman(word)}</p>`:''}<p class="question-help">这个词的中文意思是？</p></div><div class="answer-grid">${question.options.map((answer,i)=>`<button class="answer ${answered?(i===question.answerIndex?'correct':i===quiz.selected?'incorrect':''):''}" data-action="answer" data-index="${i}" ${answered?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span class="answer-text">${esc(answer)}${answered&&i===question.answerIndex?'<span class="answer-status">✓ 正确答案</span>':answered&&i===quiz.selected?'<span class="answer-status">✕ 你的选择</span>':''}</span></button>`).join('')}</div><div class="answer-feedback" aria-live="polite">${answered?`<span class="${correct?'success-text':'error-text'}">${correct?'回答正确'+(mode==='course'?(quiz.index===quiz.questions.length-1?' · 即将显示成绩':' · 即将进入下一题'):''):'正确答案：'+esc(question.answer)}</span>${button((quiz.index===quiz.questions.length-1?'查看成绩':'下一题')+icon('right'),'next-question','primary')}`:'<span>每题选择一次；也可以按 1–4 选择答案。</span>'}</div></section>`;

}

function answerQuestion(index){

  if(!quiz||quiz.complete||quiz.selected!==null||!Number.isInteger(index))return;

  const q=quiz.questions[quiz.index];if(!q.options[index])return;

  cancelAudio();quiz.selected=index;

  const correct=quiz.selected===q.answerIndex;if(correct)quiz.score++;else if(quiz.mode==='course'&&!quiz.wrongIds.includes(q.id))quiz.wrongIds.push(q.id);

  render();

  if(correct)scheduleQuizAdvance();

}

function nextQuestion(){if(!quiz||quiz.complete||quiz.selected===null)return;cancelQuizAdvance();cancelAudio();quiz.index++;quiz.selected=null;if(quiz.index>=quiz.questions.length){quiz.complete=true;if(quiz.mode==='course'){progress[quiz.level].best_score=Math.max(progress[quiz.level].best_score,Math.round(quiz.score/quiz.questions.length*100));saveProgress();}}render();if(!quiz.complete)playCurrentQuestion();}

function startWrongStudy(){

  if(state.view!=='quiz'||!quiz?.complete||quiz.mode!=='course'||!quiz.wrongIds?.length)return;

  cancelQuizAdvance();cancelAudio();

  wrongStudy={ids:[...new Set(quiz.wrongIds)].filter(id=>byId.has(id)),index:0,done:new Set(),history:[]};

  render();

}

function advanceWrongStudy(master=false){

  if(!wrongStudy||state.view!=='quiz')return;

  const word=currentWord();if(!word)return;cancelAudio();

  if(master&&!isLearned(word)){progress[word.level].learned.push(word.thai);saveProgress();}

  wrongStudy.done.add(word.id);

  const next=wrongStudy.ids.findIndex((id,i)=>i>wrongStudy.index&&!wrongStudy.done.has(id));

  const target=next>=0?next:wrongStudy.ids.findIndex(id=>!wrongStudy.done.has(id));

  if(target<0){clearWrongWords();quiz.wrongStudyDone=true;render();return;}

  wrongStudy.history.push(wrongStudy.index);wrongStudy.index=target;render();

}

function previousWrongStudy(){

  if(!wrongStudy||!wrongStudy.history.length)return;

  cancelAudio();wrongStudy.index=wrongStudy.history.pop();render();

}

function renderWrongStudy(){

  const word=currentWord(),total=wrongStudy.ids.length,done=wrongStudy.done.size;

  $('#main').innerHTML=heading('错词学习','仅学习本轮答错的词汇；学完或离开此页后自动清空。','<div class="quiz-heading-actions">'+button('再来一轮','restart-quiz','soft')+button('返回词汇学习','go-study','ghost')+'</div>')+

  `<div class="session-banner"><p>本轮错词 <strong>${total}</strong> 个 · 已学 <strong>${done} / ${total}</strong> 个</p><div class="progress-track" role="progressbar" aria-label="错词学习进度" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><span style="width:${percent(done,total)}%"></span></div></div><div class="study-layout"><div class="learning-column"><article class="word-card wrong-word-card"><div class="word-meta"><span class="tag">${word.level} · 错词学习</span><span>${wrongStudy.index+1} / ${total}</span></div><div class="word-center"><h2 class="word-thai ${word.thai.length>18?'long':''}" lang="th">${esc(word.thai)}</h2><p class="pron">${roman(word)}</p><p class="word-cn"><span>${esc(word.senses.map(s=>s.cn).join(' / '))}</span></p>${audioButton(word.audio,'播放单词 '+word.thai,false)}</div><div class="word-footer">${button(icon('left')+'上一个','wrong-previous','ghost',!wrongStudy.history.length?'disabled':'')}${button(icon('check')+'已掌握','wrong-master','primary')}${button('下一个'+icon('right'),'wrong-next','ghost')}</div></article>${examples(word)}</div>${studyRail(word)}</div>`;

}



function renderDictionary(){

  const f=state.filters,positions=['全部词性','原课程',...[...new Set(words.flatMap(w=>w.pos||[]))].sort()];

  $('#main').innerHTML=heading('词库检索',`全部 ${format(words.length)} 个词汇，按泰语、中文或罗马音查找，优先显示直接对应的释义。`)+`<section class="filter-panel" aria-label="检索条件"><div class="search-row"><div class="searchbox">${icon('search')}<input id="search-input" aria-label="搜索词汇" placeholder="搜索泰语、中文或罗马音…" value="${esc(f.term)}" autocomplete="off"></div>${button('搜索','search','primary')}</div><div class="filters"><select id="level-filter" aria-label="筛选等级">${['全部等级',...levels].map(x=>`<option value="${esc(x)}" ${x===f.level?'selected':''}>${x}</option>`).join('')}</select><select id="pos-filter" aria-label="筛选词性">${positions.map(x=>`<option value="${esc(x)}" ${x===f.pos?'selected':''}>${esc(x)}</option>`).join('')}</select><label><input id="unlearned-filter" type="checkbox" ${f.unlearned?'checked':''}>仅未掌握</label></div></section><div id="dictionary-results"></div>`;

  renderDictionaryResults();

}

function highlightSearch(text,term){

  text=String(text??'');const q=String(term??'').trim().toLocaleLowerCase();if(!q)return esc(text);

  const lower=text.toLocaleLowerCase();let start=0,at,html='';

  while((at=lower.indexOf(q,start))!==-1){html+=esc(text.slice(start,at))+'<mark>'+esc(text.slice(at,at+q.length))+'</mark>';start=at+q.length;}

  return html+esc(text.slice(start));

}

function dictionaryMeaning(word){

  const match=searchMatch(word,state.filters.term),chinese=match?.kind==='chinese';

  const meaning=chinese?match.definition:word.cn;

  return `<span class="search-definition">${highlightSearch(meaning,state.filters.term)}</span>${chinese&&match.secondary?`<small class="search-match-note">匹配其他义项 · 常用释义：${esc(word.cn)}</small>`:''}${isLearned(word)?' <span class="tag learned">已掌握</span>':''}`;

}

function renderDictionaryResults(){

  // Keep the current search results and ordering when only the language changes.

  const key=JSON.stringify([state.filters,levels.map(l=>progress[l].learned)]);

  if(dictionarySnapshot?.key!==key)dictionarySnapshot={key,ids:filterWords(words,progress,levels,state.filters).map(w=>w.id)};

  const matches=dictionarySnapshot.ids.map(id=>byId.get(id)),pages=Math.max(1,Math.ceil(matches.length/100));state.dictPage=Math.max(0,Math.min(state.dictPage,pages-1));

  const slice=matches.slice(state.dictPage*100,state.dictPage*100+100);

  $('#dictionary-results').innerHTML=matches.length?`<div class="dictionary-list"><div class="dict-row dict-header"><span>泰语词汇</span><span>中文释义</span><span class="dict-level">等级</span><span>操作</span></div>${slice.map(w=>`<article class="dict-row"><button class="dict-thai" lang="th" data-action="detail" data-id="${w.id}">${esc(w.thai)}</button><div class="dict-cn">${dictionaryMeaning(w)}</div><div class="dict-level"><span class="tag">${w.level}</span></div><div class="dict-actions">${audioButton(w.audio,'播放 '+w.thai)}<button class="icon-button" data-action="study-word" data-id="${w.id}" aria-label="学习 ${esc(w.thai)}" title="学习这个词">${icon('right')}</button></div></article>`).join('')}</div><div class="pagination"><span>共 ${format(matches.length)} 个词汇</span><div>${button('上一页','dict-prev','small',state.dictPage===0?'disabled':'')}<span>${state.dictPage+1} / ${pages}</span>${button('下一页','dict-next','small',state.dictPage>=pages-1?'disabled':'')}</div></div>`:`<section class="word-card empty"><h2>没有找到匹配的词汇</h2><p>换个关键词，或减少筛选条件再试试。</p>${button('清除筛选','clear-filters','soft')}</section>`;

}

function safeLink(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}

function showDetail(id){const w=byId.get(id);if(!w)return;showModal(`<span class="tag">${w.level}</span><h2 class="word-thai long" lang="th">${esc(w.thai)}</h2><p>${roman(w)}</p>${w.ipa?`<p>IPA：${esc(w.ipa)}</p>`:''}<ol class="detail-definitions">${w.senses.map(s=>`<li>${esc(s.cn)}</li>`).join('')}</ol><p>词性：${esc((w.pos||[]).join(' / ')||'基础课程')}<br>分级依据：${esc(w.grade_reason||'原课程安排')}</p>${w.source?`<p><a href="${esc(safeLink(w.source))}" target="_blank" rel="noopener noreferrer">查看原始词条 ↗</a></p>`:''}${audioButton(w.audio,'播放 '+w.thai,false)} ${button('学习这个词','study-word','primary',`data-id="${w.id}"`)}`);detailId=id;}

function renderProgress(){

  const n=totalLearned(),d=progress._daily?.date===localDate()?progress._daily:null,done=d?.studied.length||0,target=d?done+d.words.length-d.done.length:10;

  $('#main').innerHTML=heading('学习进度','每一次记住，都在积累。')+`<div class="stats-grid"><article class="stat-card"><small>累计已掌握</small><strong>${format(n)}<span>个词汇</span></strong></article><article class="stat-card"><small>总完成比例</small><strong>${percent(n,words.length)}<span>%</span></strong></article><article class="stat-card"><small>今日已学</small><strong>${done}<span>/ ${target} 个</span></strong></article></div>${levels.map(l=>{const total=words.filter(w=>w.level===l).length,count=progress[l].learned.length;return `<section class="level-progress"><div class="level-progress-head"><div><h3>${l}</h3><p>${count} / ${total} 个词汇 · ${percent(count,total)}%</p></div><span class="best">历史最高 <strong>${progress[l].best_score}</strong> 分</span>${button('继续学习','study-level','small',`data-level="${l}"`)}</div><div class="progress-track" role="progressbar" aria-label="${l}完成比例" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent(count,total)}"><span style="width:${percent(count,total)}%"></span></div></section>`;}).join('')}${Object.keys(progress._legacy_scores).length?`<p class="note">旧版历史成绩：${Object.entries(progress._legacy_scores).map(([l,s])=>esc(l)+' '+esc(s)+' 分').join(' · ')}</p>`:''}<div class="progress-controls">${button(icon('download')+'导出进度','export')}${button(icon('upload')+'导入进度','import')}${button('来源与说明','sources','ghost')}</div><p class="note">每位访客的进度独立保存在当前浏览器中。同一浏览器再次访问可继续学习；换设备、换浏览器、更换网址或清除浏览器数据前，请导出备份，再在新环境中导入。共用同一浏览器会使用同一份进度。</p>`;

}

function exportProgress(){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`thai_progress_${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习进度已导出。');}

function showSources(){showModal(`<h2>词库来源与说明</h2><p>本地版包含 ${format(words.length)} 个词汇、${format(words.reduce((n,w)=>n+w.senses.length,0))} 个义项，以及 ${format(data.metadata.audio_count)} 段离线音频。</p><p>本次新增 2,528 个词，释义主要整理自 Belisan 的 <a href="https://belisan-volubilis.blogspot.com/" target="_blank" rel="noopener noreferrer">VOLUBILIS 泰中词典</a>（CC BY-SA 4.0），例句参考 <a href="https://opend-portal.nectec.or.th/en/dataset/lexitron-2-0" target="_blank" rel="noopener noreferrer">NECTEC / LEXiTRON 2.0</a>、维基词典，并补充教学例句。</p><p>LEXiTRON 使用随附的<a href="licenses/LEXiTRON-LICENSE.txt" target="_blank" rel="noopener noreferrer">独立许可</a>。This product is created by the adaptation of LEXiTRON developed by NECTEC (http://www.nectec.or.th/).</p><p>原词典来自中文维基词典贡献者，补充读音与部分例句来自英文维基词典贡献者，经 <a href="https://kaikki.org/dictionary/Thai/index.html" target="_blank" rel="noopener noreferrer">Kaikki.org / Wiktextract</a> 整理，遵循 <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>。</p><p>词义和例句经过 AI 辅助校订。学习等级结合语料词频与日常交流需求，早餐、午餐等基础生活词优先学习，各级不设固定名额。原始词频数据仍保留，分级调整不影响已掌握记录。</p><p>另补充 79 个例句常用词为独立学习词条，包含“溶解”。保留原词条编号，并复用已有例句及统一女声音频。</p><p>程序从随附 audio 文件夹播放 MP3，学习时不调用在线语音服务。浏览器若限制自动发音，请点击词语旁的喇叭。</p><p>进度独立保存在当前浏览器。扩充词库保留原词条编号和个人进度。</p><p><a href="licenses/SOURCES.md" target="_blank" rel="noopener noreferrer">完整来源、修改说明与授权</a></p>`);}

const actions={

  'study-mistakes':startWrongStudy,'wrong-next':()=>advanceWrongStudy(),'wrong-master':()=>advanceWrongStudy(true),'wrong-previous':previousWrongStudy,

  'next':()=>advance(),'master':()=>advance(true),'previous':previous,

  'quiz-level':b=>{if(!levels.includes(b.dataset.level))return;clearWrongWords();state.quizLevel=b.dataset.level;quiz=null;cancelQuizAdvance();cancelAudio();saveProgress();render();},

  'level':b=>setLevel(b.dataset.level),'study-level':b=>{setLevel(b.dataset.level);preserveStudySelection=true;setView('study');},

  'go-study':()=>{clearWrongWords();setView('study');},'go-progress':()=>setView('progress'),

  'daily-again':()=>{if(state.view!=='daily')return;cancelAudio();startDailyRound(progress,words,levels);syncDaily();saveProgress();render();},

  'finish-daily':()=>{cancelAudio();saveProgress();setView('progress');},

  'choose-quiz-level':()=>{clearWrongWords();quiz=null;cancelQuizAdvance();cancelAudio();render();},

  'start-review':()=>startQuiz('review'),'start-quiz':()=>startQuiz('course'),

  'restart-quiz':()=>{clearWrongWords();if(state.view==='quiz'){quiz=null;cancelQuizAdvance();cancelAudio();render();return;}const mode=state.view==='review'?'review':'course';if(quiz&&!quiz.complete&&quiz.mode===mode){showModal(`<h2>开始新的一轮？</h2><p>当前这一轮的答题进度将结束。</p>${button('继续本轮','close-modal')}${button('重新开始','confirm-restart','primary')}`);}else startQuiz(mode);},

  'confirm-restart':()=>{closeModal();if(state.view==='quiz'){quiz=null;cancelQuizAdvance();cancelAudio();render();}else startQuiz('review');},

  'answer':b=>answerQuestion(Number(b.dataset.index)),'next-question':nextQuestion,

  'search':()=>{dictionarySnapshot=null;clearTimeout(filterTimer);state.filters.term=$('#search-input').value;state.dictPage=0;renderDictionaryResults();},

  'dict-prev':()=>{state.dictPage--;renderDictionaryResults();},'dict-next':()=>{state.dictPage++;renderDictionaryResults();$('#main').scrollIntoView({behavior:'smooth'});},

  'clear-filters':()=>{state.filters={term:'',level:'全部等级',pos:'全部词性',unlearned:false};state.dictPage=0;renderDictionary();},

  'detail':b=>showDetail(Number(b.dataset.id)),

  'study-word':b=>{const w=byId.get(Number(b.dataset.id));if(!w)return;closeModal();state.level=w.level;state.wordId=w.id;state.history=[];preserveStudySelection=true;setView('study');},

  'sources':showSources,'close-modal':closeModal,'export':exportProgress,

  'import':()=>$('#import-file').click(),

  'confirm-import':()=>{if(!pendingImport)return;progress=mergeProgress(progress,pendingImport,words,levels);closeModal();if(state.view==='daily')syncDaily();saveProgress();render();toast('已合并进度，保留所有已掌握词汇和最高成绩。');}

};

document.addEventListener('click',event=>{const a=event.target.closest('[data-audio]');if(a&&!a.disabled){playManualAudio(a);return;}const b=event.target.closest('[data-action]');if(b&&!b.disabled&&progress)actions[b.dataset.action]?.(b);});

$('#mute-button').addEventListener('click',()=>{if(!progress)return;state.muted=!state.muted;if(state.muted)cancelAudio();updateMute();saveProgress();toast(state.muted?'已静音，自动发音与重播均已关闭。':'已取消静音。');});

document.addEventListener('input',event=>{if(event.target.id==='search-input'){state.filters.term=event.target.value;state.dictPage=0;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{if(state.view==='dictionary')renderDictionaryResults();},140);}});

document.addEventListener('change',event=>{const id=event.target.id;if(id==='level-filter')state.filters.level=event.target.value;else if(id==='pos-filter')state.filters.pos=event.target.value;else if(id==='unlearned-filter')state.filters.unlearned=event.target.checked;else return;state.dictPage=0;renderDictionaryResults();});

$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>2_000_000)throw Error('文件过大，请选择学习进度 JSON 文件');const raw=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(!Object.keys(raw).some(k=>!k.startsWith('_')))throw Error('未找到有效课程进度');pendingImport=normalizeProgress(raw,words,levels);const count=levels.reduce((n,l)=>n+pendingImport[l].learned.length,0);showModal(`<h2>导入学习进度</h2><p>将「${esc(file.name)}」与当前进度合并。</p><p class="import-summary">文件包含 ${count} 个已掌握词汇。<br>保留两份进度中的已掌握词汇与最高成绩。</p>${button('取消','close-modal')}${button('确认合并','confirm-import','primary')}`);}catch(error){pendingImport=null;toast('导入失败：'+error.message);}});

$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});

document.addEventListener('keydown',event=>{if(!progress||$('#modal').open||event.ctrlKey||event.altKey||event.metaKey||event.target.closest('input,textarea,select,[contenteditable=true]'))return;if(wrongStudy&&state.view==='quiz'){if(event.key==='ArrowRight'){event.preventDefault();advanceWrongStudy();}if(event.key==='ArrowLeft'){event.preventDefault();previousWrongStudy();}}else if(['study','daily'].includes(state.view)){if(event.key==='ArrowRight'){event.preventDefault();advance();}if(event.key==='ArrowLeft'){event.preventDefault();previous();}}else if(['quiz','review'].includes(state.view)&&quiz&&!quiz.complete){if(!event.repeat&&/^[1-4]$/.test(event.key))answerQuestion(Number(event.key)-1);if(event.key==='ArrowRight'&&quiz.selected!==null)nextQuestion();}});

window.addEventListener('hashchange',()=>{if(progress)route();});

window.addEventListener('pagehide',clearWrongWords);

window.addEventListener('pageshow',event=>{if(event.persisted&&progress)render();});

document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAudio();});

function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});const specs=[{name:'get_learning_status',description:'Read current learning view, current word and mastery counts.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view:state.view,word:currentWord()?.thai||null,learned:totalLearned(),total:words.length})},{name:'start_daily_learning',description:'Open today’s unmastered word session, creating today’s 10-word selection if needed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>{history.replaceState(null,'','#daily');route();await saveQueue;return{words:progress._daily.words,completed:progress._daily.done.length};}},{name:'mark_current_word_learned',description:'Mark the visible study word as learned and advance to the next word.',inputSchema:{type:'object',properties:{thai:{type:'string'}},required:['thai'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!['study','daily'].includes(state.view)||!input||typeof input.thai!=='string'||Object.keys(input).length!==1||currentWord()?.thai!==input.thai)throw Error('The requested word is not the current study word.');advance(true);await saveQueue;return{learned:input.thai,next:currentWord()?.thai||null};}}];for(const spec of specs){try{Promise.resolve(context.registerTool(spec,{signal:life.signal})).catch(()=>{});}catch{}}}

function refreshLocalizedData(){

  data=localizeData(structuredClone(sourceData));words=data.words;levels=data.level_names;

  byId=new Map(words.map(w=>[w.id,w]));byThai=new Map(words.map(w=>[w.thai,w]));

  $('#word-count').textContent=`${format(words.length)} 个词汇 · 六级课程`;

}

onLocaleChange(()=>{

  if(!sourceData)return;

  refreshLocalizedData();

  if(!progress)return;

  if(quiz)for(const question of quiz.questions){

    question.options=question.optionIds.map(id=>byId.get(id).cn);

    question.answer=question.options[question.answerIndex];

  }

  // Render the existing state; routing would pick a new word or daily session.

  render();

  if($('#modal').open&&detailId!==null){

    const top=$('#modal').scrollTop;showDetail(detailId);$('#modal').scrollTop=top;

  }

});

try{

  const response=await fetch('data.json?v=20261021-scene-usage-48k-1',{cache:'no-store'});if(!response.ok)throw Error('词库文件无法读取');sourceData=await response.json();refreshLocalizedData();

  let raw={};

  try{raw=JSON.parse(localStorage.getItem(STORAGE)||'{}')||{};}

  catch{toast('浏览器进度无法读取，可在学习进度页导入备份。');}

  progress=normalizeProgress(raw,words,levels);state.muted=progress._web?.muted===true;state.quizLevel=progress._web?.quizLevel||levels[0];state.wordId=randomUnlearnedId();$('#save-status').textContent='个人进度已载入';route();registerTools();

}catch(error){$('#main').innerHTML=`<section class="word-card empty"><h1>暂时无法打开学习空间</h1><p>${esc(error.message)}</p><p>请使用“启动网页版”打开，并确认网页目录完整。</p>${button('重新加载','reload','primary')}</section>`;document.querySelector('[data-action=reload]').onclick=()=>location.reload();$('#save-status').textContent='加载失败';}

